// enumerate each unoriented cut once, by fixing vertex 26 outside. Accept sizes 13 AND 14. Prune by fixed-to-fixed crossing cost plus unavoidable free-to-fixed cost with prescribed cardinality (degree independent).
use std::io::{self,BufRead};fn rec(a:&[u32],i:usize,s:u32,t:u32,cut:u32,best:&mut u32,ms:&mut Vec<u32>){let x=s.count_ones();let y=t.count_ones();if x>14||y>14||cut>*best{return}if i==26{if cut<*best{ms.clear();*best=cut}ms.push(if x==13{s}else{((1<<27)-1)^s});return}if i>=10{let mut lo=cut;for &v in &a[i..26]{lo+=(v&s).count_ones().min((v&t).count_ones())}if lo>*best{return}}let v=a[i];let bit=1<<i;rec(a,i+1,s|bit,t,cut+(v&t).count_ones(),best,ms);rec(a,i+1,s,t|bit,cut+(v&s).count_ones(),best,ms)}fn main(){for l in io::stdin().lock().lines(){let a:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let mut best=999;let mut ms=vec![];rec(&a,0,0,1<<26,0,&mut best,&mut ms);print!("{}",best);for s in ms{print!(" {}",s)}println!()}}
